{"cards": [{"node_code": "N_3655520b8653beeb", "definition": "研究线性反馈控制系统的基本结构、传递函数推导及系统稳定性判据，涵盖开环/闭环特性分析及劳斯、奈奎斯特等经典稳定性方法。", "boundary": "聚焦于系统建模基础与稳定性理论，是频域设计的前提。边界在于处理线性定常系统的输入输出关系，不涉及具体的控制器参数整定或校正网络设计（归入“根轨迹、频率响应与校正”），也不涉及状态空间描述或非线性稳定性分析。", "includes": ["反馈控制结构、方框图化简及闭环传递函数推导", "劳斯-赫尔维茨判据、奈奎斯特稳定判据及相角/幅值裕度分析", "开环极点零点分布对闭环稳定性的影响分析"], "excludes": ["基于状态空间模型的稳定性分析或李雅普诺夫方法", "具体的PID参数整定或超前/滞后校正网络设计"], "sibling_distinctions": [{"other_code": "N_7de067f6a39a90be", "rule": "本节点关注系统固有稳定性及传递函数基础，兄弟节点关注利用根轨迹或频域特性进行控制器设计与性能校正。"}, {"other_code": "N_26113a6ff06bc34f", "rule": "本节点提供稳定性理论框架，兄弟节点关注特定控制器（PID）的结构实现与参数调整策略。"}], "cross_boundary_rule": "若稳定性分析直接服务于控制器校正设计，主挂载本节点，校正设计细节可次关联“根轨迹、频率响应与校正”。"}, {"node_code": "N_7de067f6a39a90be", "definition": "研究利用根轨迹法、Bode图、Nyquist图等工具分析系统动态特性，并设计超前、滞后或PID校正网络以优化系统性能的方法。", "boundary": "聚焦于控制器的综合设计与性能指标（如超调、调节时间、稳态误差）的优化。边界在于基于已建立的传递函数模型进行图形化或解析化设计，不涉及稳定性判据的基础推导（归入“反馈、传递函数与稳定性”），也不涉及非线性或时变系统的校正。", "includes": ["根轨迹绘制规则、增益对极点移动的影响及闭环极点配置", "Bode图、Nyquist图、Nichols图分析及频域性能指标（带宽、谐振峰等）", "超前、滞后、滞后-超前校正网络设计及PID参数在频域下的整定"], "excludes": ["基于状态空间的最优控制或极点配置设计", "非线性系统的描述函数法或相平面校正"], "sibling_distinctions": [{"other_code": "N_3655520b8653beeb", "rule": "本节点关注如何利用频域/根轨迹工具设计控制器以满足性能指标，兄弟节点关注系统是否稳定及传递函数的基本推导。"}, {"other_code": "N_26113a6ff06bc34f", "rule": "本节点涵盖广义的校正网络设计（含PID），兄弟节点专门深入PID控制器的结构细节、整定经验及抗饱和工程实现。"}], "cross_boundary_rule": "若校正设计仅涉及PID参数调整且强调工程整定经验，可次关联“PID控制、整定与抗饱和”；若涉及超前/滞后网络或复杂频域指标优化，主挂载本节点。"}, {"node_code": "N_26113a6ff06bc34f", "definition": "研究比例-积分-微分（PID）控制器的结构、参数整定方法、工程实现细节及抗积分饱和、无扰切换等高级应用策略。", "boundary": "聚焦于PID这一特定控制器的理论、整定及工程鲁棒性处理。边界在于以PID为核心对象，不涉及其他类型校正网络（如超前/滞后）的通用设计（归入“根轨迹、频率响应与校正”），也不涉及状态空间下的最优PID设计。", "includes": ["P、PI、PID控制器的传递函数结构及变体（如位置式/增量式）", "经验整定法（Ziegler-Nichols等）、频域整定及基于模型的整定方法", "积分抗饱和（Anti-windup）、无扰切换（Bumpless transfer）及两自由度PID结构"], "excludes": ["非PID类型的控制器设计（如模糊控制、神经网络控制）", "基于状态空间的最优控制律推导"], "sibling_distinctions": [{"other_code": "N_7de067f6a39a90be", "rule": "本节点专门深入PID控制器的工程实现细节（如抗饱和、无扰切换），兄弟节点关注更广泛的频域校正网络设计及通用性能指标优化。"}, {"other_code": "N_3655520b8653beeb", "rule": "本节点关注具体控制器的参数调整与工程应用，兄弟节点关注系统稳定性基础理论及传递函数分析。"}], "cross_boundary_rule": "PID参数整定若基于频域指标（如相位裕度），可次关联“根轨迹、频率响应与校正”；但PID结构、抗饱和及无扰切换等工程特性主挂载本节点。"}]}
